var tr = doc.ActiveProjectLocation.GetTotalTransform().Inverse;
var res = new List<object>();
foreach (var li in new FilteredElementCollector(doc).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>()) {
  var nm = doc.GetElement(li.GetTypeId()).Name;
  if (!(nm.Contains("Building 03 Shell") || nm.Contains("Building 03 Internal"))) continue;
  var ld = li.GetLinkDocument(); if (ld == null) continue;
  var t = li.GetTotalTransform();
  double minX=double.MaxValue,minY=double.MaxValue,maxX=double.MinValue,maxY=double.MinValue; int n=0;
  foreach (var w in new FilteredElementCollector(ld).OfCategory(BuiltInCategory.OST_Walls).WhereElementIsNotElementType()) {
    var bb = w.get_BoundingBox(null); if (bb==null) continue; n++;
    foreach (var p in new[]{bb.Min, bb.Max}) { var q = tr.OfPoint(t.OfPoint(p)); minX=Math.Min(minX,q.X);minY=Math.Min(minY,q.Y);maxX=Math.Max(maxX,q.X);maxY=Math.Max(maxY,q.Y);} }
  var lp = ld.ActiveProjectLocation.GetProjectPosition(XYZ.Zero);
  res.Add(new { nm, walls = n, sharedE = new[]{ Math.Round(minX*0.3048,1), Math.Round(maxX*0.3048,1)}, sharedN = new[]{Math.Round(minY*0.3048,1), Math.Round(maxY*0.3048,1)},
    linkSite = ld.ActiveProjectLocation.Name, linkOriginEN = new { E = Math.Round(lp.EastWest*0.3048,3), N = Math.Round(lp.NorthSouth*0.3048,3), ang = Math.Round(lp.Angle*180/Math.PI,3) } });
}
return res;
